import React, { useEffect, useState } from 'react';
import { Card, Row, Col, Statistic, Table, Space, Button, Typography, Tag, Input, Select, message, Switch } from 'antd';
import HyperloopDSLValidator from '../components/HyperloopDSLValidator';
import { normalizeHyperloopDSL } from '../utils/hyperloopDsl';

const { Title, Text } = Typography;

type P95Summary = {
  hyperloop_rs_latency_ms?: Record<string, any>;
  rsbus_latency_ms?: Record<string, any>;
  backpressure?: { total_hits?: number; per_op?: Record<string, { count: number }> };
  error_rate?: Record<string, number>;
  mismatch_rate?: Record<string, number>;
  mode?: string | null;
  canary_share?: number | null;
};

const buildAuthHeaders = () => {
  let tgId: string | null = null;
  try { tgId = sessionStorage.getItem('tg_id'); } catch {}
  return tgId ? { 'X-Telegram-User-ID': String(tgId) } : {};
};

// Нормализация вынесена в '../utils/hyperloopDsl'

const RSDashboard: React.FC = () => {
  const [loading, setLoading] = useState(false);
  const [summary, setSummary] = useState<P95Summary | null>(null);
  const [parity, setParity] = useState<any>(null);
  const [rawCounters, setRawCounters] = useState<{ requests?: number; errors?: number }>({});
  // DSL вынесен в общий компонент
  const [nightly, setNightly] = useState<any[]>([]);
  // Сырые Prometheus метрики и топ ошибок
  const [rawProm, setRawProm] = useState<string>('');
  const [errorTop, setErrorTop] = useState<Array<{ cls: string; count: number }>>([]);
  // Two-Keys профиль
  const [profile, setProfile] = useState<'prod_safe'|'dev_full'|'rs_canary_profile'>('prod_safe');
  const [reason, setReason] = useState<string>('profile switch');
  const [twoKeysId, setTwoKeysId] = useState<string>('');
  // Тренды
  const [trendSource, setTrendSource] = useState<'rsbus'|'hyperloop'>('rsbus');
  const [trendKey, setTrendKey] = useState<string>('');
  // Автообновление
  const [autoRefresh, setAutoRefresh] = useState<boolean>(true);
  const [refreshSec, setRefreshSec] = useState<number>(5);

  const loadData = async () => {
    try {
      setLoading(true);
      const h = buildAuthHeaders();
      const dash = await fetch('/api/admin/rs/dashboard/summary', { headers: h });
      if (dash.ok) {
        const d = await dash.json();
        setSummary(d?.p95 || {});
        setRawCounters({ requests: d?.counters?.rsbus_requests_total || 0, errors: d?.counters?.rsbus_errors_total || 0 });
      }
      const p = await fetch('/api/admin/rs/parity/summary', { headers: h });
      if (p.ok) setParity(await p.json());
      const n = await fetch('/api/admin/rs/nightly/recent?limit=7', { headers: h });
      if (n.ok) {
        const nj = await n.json();
        setNightly(nj?.items || []);
      }
    } catch { /* noop */ } finally { setLoading(false); }
  };

  // runDSL и состояние перенесены внутрь HyperloopDSLValidator

  useEffect(() => { void loadData(); }, []);

  useEffect(() => {
    if (!autoRefresh) return;
    const t = setInterval(() => { void loadData(); }, Math.max(2000, refreshSec * 1000));
    return () => clearInterval(t);
  }, [autoRefresh, refreshSec]);

  const loadRawProm = async () => {
    try {
      const resp = await fetch('/api/admin/rs/metrics-raw', { headers: buildAuthHeaders() });
      if (!resp.ok) throw new Error('raw');
      const data = await resp.json();
      const prom: string = String((data && (data.prom || (data.rs_raw && data.rs_raw.result && data.rs_raw.result.prom))) || '');
      setRawProm(prom);
      const map: Record<string, number> = {};
      for (const line of prom.split('\n')) {
        const m = line.match(/^rsbus_errors_total\{[^}]*class=\"([^\"]+)\"[^}]*\}\s+(\d+)/);
        if (m) {
          const cls = m[1];
          const val = Number(m[2] || 0);
          map[cls] = (map[cls] || 0) + (isFinite(val) ? val : 0);
        }
      }
      const arr = Object.entries(map).map(([cls, count]) => ({ cls, count })).sort((a,b)=>b.count-a.count).slice(0, 10);
      setErrorTop(arr);
    } catch {
      message.error('Не удалось загрузить сырые метрики');
    }
  };

  const runTwoKeysRequest = async () => {
    try {
      const cmd = `TWO_KEYS.REQUEST operation=FLAGS.APPLY_PROFILE scope=\"rs.profile\" reason=\"${reason.replace(/\"/g,'\\\"')}\" ttl_minutes=5`;
      const body = { commands: normalizeHyperloopDSL(cmd) };
      const resp = await fetch('/api/hyperloop/execute', { method:'POST', headers: { ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify(body) });
      if (!resp.ok) throw new Error('request');
      const data = await resp.json();
      const rid = (data && (data.results && data.results[0] && data.results[0].data && data.results[0].data.request_id)) || data?.data?.request_id || data?.request_id || '';
      if (!rid) throw new Error('no id');
      setTwoKeysId(rid);
      message.success('Заявка создана');
    } catch {
      message.error('Не удалось создать заявку Two-Keys');
    }
  };

  const runTwoKeysApprove = async () => {
    try {
      if (!twoKeysId) { message.warning('Нет request_id'); return; }
      const cmd = `TWO_KEYS.APPROVE id=\"${twoKeysId}\"`;
      const body = { commands: normalizeHyperloopDSL(cmd) };
      const resp = await fetch('/api/hyperloop/execute', { method:'POST', headers: { ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify(body) });
      if (!resp.ok) throw new Error('approve');
      message.success('Заявка одобрена');
    } catch {
      message.error('Не удалось одобрить заявку');
    }
  };

  const applyProfileWithTwoKeys = async () => {
    try {
      if (!twoKeysId) { message.warning('Нет request_id'); return; }
      const cmd = `FLAGS.APPLY_PROFILE name=\"${profile}\" two_keys_request_id=\"${twoKeysId}\"`;
      const body = { commands: normalizeHyperloopDSL(cmd) };
      const resp = await fetch('/api/hyperloop/execute', { method:'POST', headers: { ...buildAuthHeaders(), 'Content-Type':'application/json' }, body: JSON.stringify(body) });
      if (!resp.ok) throw new Error('apply');
      message.success(`Профиль ${profile} применён`);
      await loadData();
    } catch {
      message.error('Не удалось применить профиль');
    }
  };

  const bpTotal = summary?.backpressure?.total_hits || 0;
  const mode = summary?.mode || null;
  const canaryShare = typeof summary?.canary_share === 'number' ? summary?.canary_share : null;

  const rsbusCols = [
    { title: 'op', dataIndex: 'op' },
    { title: 'p50', dataIndex: 'p50' },
    { title: 'p95', dataIndex: 'p95' },
    { title: 'p99', dataIndex: 'p99' },
    { title: 'avg', dataIndex: 'avg' },
    { title: 'count', dataIndex: 'count' },
    { title: 'error_rate', dataIndex: 'er' },
    { title: 'mismatch_rate', dataIndex: 'mr' },
    { title: 'bp_hits', dataIndex: 'bp' },
  ];
  const rsbusData = Object.entries(summary?.rsbus_latency_ms || {}).map(([op, vals]: any) => ({
    key: op,
    op,
    p50: (vals?.p50 || 0).toFixed(2),
    p95: (vals?.p95 || 0).toFixed(2),
    p99: (vals?.p99 || 0).toFixed(2),
    avg: (vals?.avg || 0).toFixed(2),
    count: Math.round(vals?.count || 0),
    er: (summary?.error_rate?.[op] ?? 0).toFixed(3),
    mr: (summary?.mismatch_rate?.[op] ?? 0).toFixed(3),
    bp: Math.round(summary?.backpressure?.per_op?.[op]?.count || 0),
  }));

  return (
    <div style={{ padding: 16 }}>
      <Space direction="vertical" size={12} style={{ width: '100%' }}>
        <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center' }}>
          <Title level={3} style={{ margin: 0 }}>RS Dashboard</Title>
          <Space>
            <Switch checked={autoRefresh} onChange={setAutoRefresh} />
            <Text type="secondary">auto-refresh</Text>
            <Input style={{ width: 80 }} value={String(refreshSec)} onChange={(e)=>{ const v=Number(e.target.value||5); if (isFinite(v)) setRefreshSec(Math.max(2, Math.min(60, v))); }} />
            <Button onClick={loadData} loading={loading}>Обновить</Button>
          </Space>
        </div>

        <Row gutter={[12,12]}>
          <Col xs={24} sm={12} md={8} lg={6}>
            <Card><Statistic title="Requests total" value={rawCounters.requests||0} /></Card>
          </Col>
          <Col xs={24} sm={12} md={8} lg={6}>
            <Card><Statistic title="Errors total" value={rawCounters.errors||0} /></Card>
          </Col>
          <Col xs={24} sm={12} md={8} lg={6}>
            <Card><Statistic title="Backpressure hits" value={bpTotal} /></Card>
          </Col>
          <Col xs={24} sm={12} md={8} lg={6}>
            <Card><Statistic title="Exec mode" valueRender={()=>(<Tag color="blue">{mode || 'n/a'}</Tag>)} value={0} /></Card>
          </Col>
        </Row>

        <Row gutter={[12,12]}>
          <Col xs={24} sm={12} md={8} lg={6}>
            <Card><Statistic title="Canary share" value={typeof canaryShare==='number' ? (canaryShare*100).toFixed(0) : 'n/a'} suffix="%" /></Card>
          </Col>
        </Row>

        <Card size="small" title="rsbus_latency_ms (per op)">
          <Table rowKey={(r)=>r.key} dataSource={rsbusData} columns={rsbusCols as any} size="small" pagination={{ pageSize: 8 }} />
        </Card>

        <Card size="small" title="Parity summary">
          <pre style={{ whiteSpace:'pre-wrap', fontSize: 12 }}>{JSON.stringify(parity||{}, null, 2)}</pre>
        </Card>

        <Card size="small" title="Nightly RS Reports (last 7)">
          {nightly.length ? (
            <Table size="small" rowKey={(r:any)=>r.id} pagination={{ pageSize: 5 }} dataSource={nightly} columns={[
              { title:'generated_at', dataIndex:'generated_at', width: 180 },
              { title:'window_days', dataIndex:'window_days', width: 100 },
              { title:'summary keys', key:'sumk', render: (_:any,r:any)=> Object.keys(r?.summary||{}).slice(0,4).join(', ') },
            ] as any} />
          ) : (<Text type="secondary">Нет ночных отчётов</Text>)}
          <Space style={{ marginTop: 8 }}>
            <Button size="small" onClick={async()=>{
              try{ const resp = await fetch('/api/admin/rs/nightly/generate', { method:'POST', headers: buildAuthHeaders() }); if(!resp.ok) throw new Error(); message.success('Nightly report generated'); await loadData(); }catch{ message.error('Не удалось сгенерировать'); }
            }}>Сгенерировать сейчас</Button>
          </Space>
        </Card>

        <HyperloopDSLValidator />

        <Card size="small" title="Профили выполнения (Two-Keys)">
          <Space direction="vertical" style={{ width:'100%' }}>
            <Space wrap>
              <Select
                style={{ minWidth: 200 }}
                value={profile}
                onChange={setProfile as any}
                options={[
                  { label: 'prod_safe', value: 'prod_safe' },
                  { label: 'dev_full', value: 'dev_full' },
                  { label: 'rs_canary_profile', value: 'rs_canary_profile' },
                ]}
              />
              <Input style={{ minWidth: 260 }} placeholder="Причина" value={reason} onChange={(e)=>setReason(e.target.value)} />
              <Input style={{ minWidth: 320 }} placeholder="Two-Keys request_id" value={twoKeysId} onChange={(e)=>setTwoKeysId(e.target.value)} />
            </Space>
            <Space wrap>
              <Button onClick={runTwoKeysRequest}>Создать заявку</Button>
              <Button onClick={runTwoKeysApprove} type="default">Одобрить заявку</Button>
              <Button onClick={applyProfileWithTwoKeys} type="primary">Применить профиль</Button>
            </Space>
          </Space>
        </Card>

        <Card size="small" title="Сырые Prometheus метрики">
          <Space direction="vertical" style={{ width:'100%' }}>
            <Space>
              <Button onClick={loadRawProm}>Загрузить</Button>
              <Text type="secondary">Показываем последние собранные RS метрики</Text>
            </Space>
            {rawProm && (
              <div style={{ maxHeight: 240, overflow:'auto', border:'1px solid var(--sp-border-primary)', borderRadius: 8 }}>
                <pre style={{ margin:0, padding:8, fontSize:12 }}>{rawProm}</pre>
              </div>
            )}
          </Space>
        </Card>

        {errorTop.length > 0 && (
          <Row gutter={[12,12]}>
            <Col xs={24} md={14}>
              <Card size="small" title="Гистограмма ошибок по классам (rsbus_errors_total)">
                {(() => {
                  const maxCount = Math.max(1, ...errorTop.map(x => x.count || 0));
                  return (
                    <div style={{ display:'flex', alignItems:'flex-end', gap:8, height: 180, padding: 8, border:'1px dashed var(--sp-border-color, #eee)', borderRadius:8, overflowX:'auto' }}>
                      {errorTop.map((it, idx) => {
                        const h = Math.max(6, Math.round(140 * (it.count || 0) / maxCount));
                        return (
                          <div key={it.cls+idx} style={{ display:'flex', flexDirection:'column', alignItems:'center' }}>
                            <div title={`${it.cls}: ${it.count}`} style={{ width: 18, height: h, background:'#ff7875', borderRadius: 3 }} />
                            <Text style={{ maxWidth: 80 }} ellipsis={{ tooltip: it.cls }}>{it.cls}</Text>
                          </div>
                        );
                      })}
                    </div>
                  );
                })()}
              </Card>
            </Col>
            <Col xs={24} md={10}>
              <Card size="small" title="Топ ошибок по классам (таблица)">
                <Table
                  size="small"
                  rowKey={(r)=>r.cls}
                  dataSource={errorTop}
                  pagination={{ pageSize: 8 }}
                  columns={[{ title:'class', dataIndex:'cls' }, { title:'count', dataIndex:'count' } ] as any}
                />
              </Card>
            </Col>
          </Row>
        )}

        <Card size="small" title="Тренды p95/p99 по nightly (за 7 записей)">
          <Space direction="vertical" style={{ width:'100%' }}>
            <Space wrap>
              <Select
                style={{ minWidth: 180 }}
                value={trendSource}
                onChange={setTrendSource as any}
                options={[
                  { label: 'rsbus (op)', value: 'rsbus' },
                  { label: 'hyperloop (phase)', value: 'hyperloop' },
                ]}
              />
              <Input style={{ minWidth: 280 }} placeholder={trendSource==='rsbus' ? 'op (пример: hyperloop.execute)' : 'phase (пример: parse|execute)'} value={trendKey} onChange={(e)=>setTrendKey(e.target.value)} />
              <Button onClick={loadData}>Обновить</Button>
            </Space>
            <div style={{ display:'flex', flexDirection:'column', gap:8 }}>
              {(() => {
                const items = nightly || [];
                const points95: number[] = [];
                const points99: number[] = [];
                for (let i = items.length - 1; i >= 0; i--) {
                  const it = items[i];
                  const sum = it?.summary || {};
                  let entry: any = undefined;
                  if (trendSource === 'rsbus') entry = (sum.rsbus_latency_ms || {})[trendKey];
                  else entry = (sum.hyperloop_rs_latency_ms || {})[trendKey];
                  const p95 = Number(entry?.p95 || 0);
                  const p99 = Number(entry?.p99 || 0);
                  points95.push(isFinite(p95) ? p95 : 0);
                  points99.push(isFinite(p99) ? p99 : 0);
                }
                const maxVal = Math.max(1, ...points95, ...points99);
                const BarRow: React.FC<{ data: number[]; color: string; label: string }> = ({ data, color, label }) => (
                  <div>
                    <div style={{ display:'flex', alignItems:'flex-end', gap:6, height: 120, border:'1px dashed var(--sp-border-color, #eee)', padding: 6, borderRadius:8 }}>
                      {data.map((v, idx) => {
                        const h = Math.max(4, Math.round(100 * v / maxVal));
                        return <div key={idx} title={`${v.toFixed(2)} ms`} style={{ width:10, height:h, background:color, borderRadius:2 }} />;
                      })}
                    </div>
                    <Text type="secondary">{label}</Text>
                  </div>
                );
                return (
                  <>
                    <BarRow data={points95} color="#52c41a" label="p95 (ms)" />
                    <BarRow data={points99} color="#722ed1" label="p99 (ms)" />
                  </>
                );
              })()}
            </div>
          </Space>
        </Card>
      </Space>
    </div>
  );
};

export default RSDashboard;


